import { Buffer } from "node:buffer";

const encodedContent: Record<string, string> = {
  "poland-work-visa-documents-from-india": "",
  "european-work-visa-options-for-indians-gcc-residents": "",
  "germany-work-visa-opportunity-card": "",
  "verify-european-job-offer-work-permit": ""
};

export const getRawBlogContent = (slug: string) => {
  const content = encodedContent[slug];
  return content ? Buffer.from(content, "base64").toString("utf8") : null;
};
